import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void layernorm_forward(const __half* __restrict__ input,
                                 __half* __restrict__ output,
                                 const __half* __restrict__ weight,
                                 const __half* __restrict__ bias,
                                 int64_t N,
                                 float eps) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int blockSize = blockDim.x;

    const __half* in_batch = input + batch_idx * N;
    __half* out_batch = output + batch_idx * N;

    // Compute partial sums
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (int i = tid; i < N; i += blockSize) {
        float v = __half2float(in_batch[i]);
        sum   += v;
        sumsq += v * v;
    }

    // Shared memory for reduction
    extern __shared__ float shmem[];
    float* sh_sum   = shmem;
    float* sh_sumsq = shmem + blockSize;

    sh_sum[tid]   = sum;
    sh_sumsq[tid] = sumsq;
    __syncthreads();

    // Parallel reduction (sum & sumsq)
    for (int stride = blockSize >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh_sum[tid]   += sh_sum[tid + stride];
            sh_sumsq[tid] += sh_sumsq[tid + stride];
        }
        __syncthreads();
    }

    float mean = sh_sum[0] / static_cast<float>(N);
    float var  = sh_sumsq[0] / static_cast<float>(N) - mean * mean;
    float inv_std = rsqrtf(var + eps);

    __syncthreads(); // ensure mean/var visible

    // Apply normalization, scale, bias
    for (int i = tid; i < N; i += blockSize) {
        float x = __half2float(in_batch[i]);
        float w = __half2float(weight[i]);
        float b = __half2float(bias[i]);
        float y = (x - mean) * inv_std;
        y = y * w + b;
        out_batch[i] = __float2half(y);
    }
}

void layernorm_forward_launcher(at::Tensor input,
                                at::Tensor output,
                                at::Tensor weight,
                                at::Tensor bias,
                                float eps) {
    const int64_t batch = input.size(0);
    const int64_t N = input.numel() / batch;   // size of normalized dimensions

    const int threads = 256;
    const dim3 blocks(batch);
    const size_t shared_mem = sizeof(float) * threads * 2; // sum + sumsq

    layernorm_forward<<<blocks, threads, shared_mem>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<const __half*>(bias.data_ptr()),
        N,
        eps);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA error in layernorm_forward: ", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &layernorm_forward_launcher, "LayerNorm forward (CUDA)");
}
'''

layernorm_ext = load_inline(name='layernorm_ext',
                            cpp_sources='',
                            cuda_sources=cuda_src,
                            functions=['forward'],
                            verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for nn.LayerNorm using a custom CUDA kernel.
    All tensors are fp16.
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        super().__init__()
        self.normalized_shape = normalized_shape
        self.eps = eps
        # weight and bias are learnable parameters matching the normalized shape
        self.weight = nn.Parameter(torch.ones(normalized_shape,
                                              dtype=torch.float16,
                                              device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(normalized_shape,
                                              dtype=torch.float16,
                                              device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 and on CUDA
        x = x.to(dtype=torch.float16, device='cuda')
        out = torch.empty_like(x)
        layernorm_ext.forward(x, out, self.weight, self.bias, self.eps)
        return out

# Example usage (mirrors reference's get_inputs):
if __name__ == "__main__":
    batch_size = 16
    features = 64
    dim1 = 256
    dim2 = 256
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    model = ModelNew((features, dim1, dim2))
    y = model(x)
    print(y.shape)  # should be (16, 64, 256, 256)
